action.code:
# Some songs might already be liked. Let me handle that gracefully
followed_artists = apis.spotify.show_following_artists(access_token=token)

# For each artist, search for their songs and like them
for artist in followed_artists:
    artist_name = artist['name']
    print(f"\nProcessing artist: {artist_name}")

    # Search for songs by this artist
    search_result = apis.spotify.search_songs(query=artist_name, access_token=token)
    print(f"Found {len(search_result)} songs")

    # Like each song
    for song in search_result:
        song_id = song['song_id']
        try:
            apis.spotify.like_song(song_id=song_id, access_token=token)
            print(f"  Liked song {song_id}: {song['title']}")
        except Exception as e:
            if "already liked" in str(e):
                print(f"  Song {song_id} already liked: {song['title']}")
            else:
                print(f"  Error liking song {song_id}: {e}")

