# Now I need to get details for all the songs to check their genres
# Let me collect all unique song IDs from liked songs, liked albums, and playlists

all_song_ids = set()

# From liked songs
for song in liked_songs_response:
    all_song_ids.add(song['song_id'])

# From liked albums
for album in liked_albums_response:
    for song_id in album['song_ids']:
        all_song_ids.add(song_id)

# From playlists
for playlist in playlists_response:
    for song_id in playlist['song_ids']:
        all_song_ids.add(song_id)

print(f"Total unique song IDs: {len(all_song_ids)}")
print(f"Song IDs: {sorted(all_song_ids)}")

