   "default": "all",
   "constraints": [
    "value in ['all', 'files', 'directories']"
   ]
  },
  {
   "name": "recursive",
   "type": "boolean",
   "required": false,
   "description": "Whether to show files recursively.",
   "default": true,
   "constraints": []
  }
 ],
