# Let me check all contacts to find Robert Martinez by contact_id 929
all_contacts = apis.phone.search_contacts(name="", access_token=phone_token)
# Find contact with id 929
robert_contact = None
for contact in all_contacts:
    if contact['contact_id'] == 929:
        robert_contact = contact
        break

if robert_contact:
    print("Robert Martinez contact:", robert_contact)
else:
    print("Contact 929 not found in results")
    print("Total contacts returned:", len(all_contacts))

# Let me try a different approach - search with page_index to see all contacts
all_contacts = []
page_index = 0
while True:
    contacts = apis.phone.search_contacts(name="", access_token=phone_token, page_index=page_index)
    if not contacts:
        break
    all_contacts.extend(contacts)
    page_index += 1

# Find Robert Martinez
robert_contact = None
for contact in all_contacts:
    if contact['first_name'] == 'Robert' and contact['last_name'] == 'Martinez':
        robert_contact = contact
        break

if robert_contact:
    print("Found Robert Martinez:", robert_contact)
else:
    print("Robert Martinez not found in contacts")
    print("Total contacts:", len(all_contacts))
    # Show first few contacts
    for c in all_contacts[:10]:
        print(f"  {c['first_name']} {c['last_name']} - {c.get('email', 'no email')}")

