action.code:
# Get details for all songs and filter for EDM genre
edm_songs = []

for song_id in sorted(all_song_ids):
    song_details = apis.spotify.show_song(song_id=song_id)
    if song_details and 'genre' in song_details:
        genre = song_details['genre'].lower()
        if 'edm' in genre or 'electronic' in genre:
            edm_songs.append({
                'title': song_details['title'],
                'song_id': song_id,
                'genre': song_details['genre'],
                'play_count': song_details.get('play_count', 0)
            })
            print(f"Found EDM song: {song_details['title']} (plays: {song_details.get('play_count', 0)})")

print(f"\nTotal EDM songs found: {len(edm_songs)}")

